package com.dsha.sidecar.net.dns.native

import com.dsha.sidecar.net.dns.SvcbCodec
import java.io.ByteArrayOutputStream
import java.io.DataOutputStream

internal object NativeEchTestData {
    /** Exact upstream-generated fixture list, copied unchanged, never generated by the code under test. */
    fun config(case: String = "single-x25519"): ByteArray {
        val fixture = checkNotNull(javaClass.getResource("/ech/ech-config.valid.json")) {
            "Missing ECH test fixture"
        }.readText()
        val start = fixture.indexOf("\"name\": \"$case\"")
        check(start >= 0) { "Missing fixture $case" }
        val hex = Regex("\"value\": \"([0-9a-f]+)\"").find(fixture, start)!!.groupValues[1]
        return hex.chunked(2).map { it.toInt(16).toByte() }.toByteArray()
    }

    fun rdata(
        ech: ByteArray? = config(),
        priority: Int = 1,
        target: String = ".",
        extra: List<Pair<Int, ByteArray>> = emptyList(),
    ): ByteArray {
        val bytes = ByteArrayOutputStream()
        DataOutputStream(bytes).apply {
            writeShort(priority)
            write(NativeDnsTestPackets.name(target.takeUnless { it == "." }.orEmpty()))
            for ((key, raw) in (extra + listOfNotNull(ech?.let { 5 to it })).sortedBy { it.first }) {
                writeShort(key); writeShort(raw.size); write(raw)
            }
        }
        return bytes.toByteArray()
    }

    fun record(
        ech: ByteArray? = config(),
        priority: Int = 1,
        target: String = ".",
        ttl: Long = 120_000,
        owner: String = "example.test",
        extra: List<Pair<Int, ByteArray>> = emptyList(),
    ) = HttpsServiceRecord(owner, ttl, SvcbCodec.decodeSvcRecord(rdata(ech, priority, target, extra), 0,
        rdata(ech, priority, target, extra).size))
}
